Файл не перезаписываю: `listUsers` меняет тип возврата, это решение автора.

```js
const USERS = new Map();

export function getUser(id, cb) {
  if (id == null) throw new TypeError("id is required");
  if (typeof cb !== "function") throw new TypeError("cb must be a function");
  let user = USERS.get(id);
  if (!user) {
    user = { id, seen: 0 };
    USERS.set(id, user);
  }
  user.seen++;
  setTimeout(() => cb(user), 0);
  return user;
}

export function deleteUser(id) {
  return USERS.delete(id);
}

export async function listUsers() {
  const responses = await Promise.all(
    [...USERS.keys()].map((id) => fetch("/api/users/" + encodeURIComponent(id)))
  );
  return Promise.all(
    responses.map((res) => {
      if (!res.ok) throw new Error(`listUsers: ${res.status} ${res.url}`);
      return res.json();
    })
  );
}
```

